// Session leaderboard: remembers every game that finishes while this layout is open, and ranks
// them. It starts empty again when you reload the layout or restart Foxglove.
// A game you reset before the final whistle doesn't count.
import { Input } from "./types";

export const inputs = ["/haunted_house/state"];
export const output = "/studio_script/leaderboard";

type Attempt = {
  rank: number;
  score: number;
  people_haunted: number;
  candies_eaten: number;
  bonks: number;
  time_used_s: number;
  finished_at: string;
};

type Leaderboard = {
  games_played: number;
  best_score: number;
  current_score: number;
  attempts: Attempt[];
};

type Result = {
  score: number;
  people_haunted: number;
  candies_eaten: number;
  bonks: number;
  time_used_s: number;
  finished_at: string;
};

// GameState phases, and the game's length in the house file
const RUNNING = 1;
const FINISHED = 2;
const DURATION_S = 120;
// How many attempts to show
const TOP = 10;

const results: Result[] = [];
let lastPhase = -1;

export default function script(event: Input<"/haunted_house/state">): Leaderboard {
  const state = event.message;

  if (state.phase === FINISHED && lastPhase === RUNNING) {
    const stamp = state.header.stamp.sec + state.header.stamp.nsec / 1e9;
    results.push({
      score: state.score,
      people_haunted: state.people_haunted,
      candies_eaten: state.candies_eaten,
      bonks: state.bonks,
      time_used_s: Math.round((DURATION_S - state.time_remaining_s) * 10) / 10,
      finished_at: new Date(stamp * 1000).toLocaleTimeString(),
    });
  }
  lastPhase = state.phase;

  // Highest score first; fewer bonks breaks a tie
  const ranked: Attempt[] = [...results]
    .sort((a, b) => b.score - a.score || a.bonks - b.bonks)
    .slice(0, TOP)
    .map((r, i) => ({ rank: i + 1, ...r }));

  return {
    games_played: results.length,
    best_score: ranked.length > 0 ? ranked[0].score : 0,
    current_score: state.score,
    attempts: ranked,
  };
}

