// Game status: the clock while a game runs, and the final score once it's over.
import { Input } from "./types";

export const inputs = ["/haunted_house/state"];
export const output = "/studio_script/status";

type Status = {
  status: string;
};

// GameState phases, and the game's length in the house file
const RUNNING = 1;
const FINISHED = 2;
const DURATION_S = 120;

export default function script(event: Input<"/haunted_house/state">): Status {
  const state = event.message;
  if (state.phase === FINISHED) {
    return { status: `Game over - final score ${state.score}` };
  }
  // Before the clock starts, show the full game length
  const remaining = state.phase === RUNNING ? state.time_remaining_s : DURATION_S;
  const seconds = Math.ceil(remaining);
  const clock = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
  return { status: `Running - ${clock} left - score ${state.score}` };
}
